@foreach($attempt->questions as $q)<section class="panel review-card"><div class="question-topline"><span class="soft-badge">Question {{ $q->sequence }}</span><span class="status-badge {{ $q->selected_option===$q->correct_option ? 'positive' : 'warning' }}">{{ $q->selected_option === null ? 'Unanswered' : ($q->selected_option===$q->correct_option ? 'Correct' : 'Incorrect') }}</span></div><h3 class="question-prompt">{{ $q->prompt }}</h3><div class="review-options">@foreach($q->options as $choice)@php $key=$choice['key']; $option=$choice['text']; @endphp<div @class(['review-option','correct'=>$key===$q->correct_option,'incorrect'=>$key===$q->selected_option && $key!==$q->correct_option])><span>{{ chr(65+$loop->index) }}.</span><span>{{ $option }}</span>@if($key===$q->correct_option)<small>Correct answer</small>@endif @if($key===$q->selected_option)<small>Your choice</small>@endif</div>@endforeach</div>@if($q->explanation)<div class="explanation"><strong>Why this answer?</strong><p>{{ $q->explanation }}</p></div>@endif</section>@endforeach
